/**
 * @summary Development-only creator-controlled response for a demo-provider request
 */
export const RespondToDemoOrderParams = zod.object({
  "id": zod.coerce.string().uuid()
})

export const respondToDemoOrderBodyOneReasonMax = 2000;

export const respondToDemoOrderBodyTwoReasonMax = 2000;

export const respondToDemoOrderBodyThreeReasonMax = 1000;



export const RespondToDemoOrderBody = zod.union([zod.object({
  "status": zod.enum(['accepted', 'completed']),
  "reason": zod.string().max(respondToDemoOrderBodyOneReasonMax).optional()
}),zod.object({
  "status": zod.literal("rejected"),
  "reason": zod.string().min(1).max(respondToDemoOrderBodyTwoReasonMax)
}),zod.object({
  "status": zod.literal("cancelled"),
  "reason": zod.string().min(1).max(respondToDemoOrderBodyThreeReasonMax)
})])

export const RespondToDemoOrderResponse = zod.object({
  "testMode": zod.literal(true),
  "testStatus": zod.string(),
  "order": zod.object({
  "id": zod.string().uuid(),
  "status": zod.enum(['pending', 'accepted', 'rejected', 'completed', 'cancelled']),
  "responseReason": zod.string().nullable(),
  "respondedAt": zod.coerce.date().nullable(),
  "cancellationReason": zod.string().nullable(),
  "cancelledAt": zod.coerce.date().nullable(),
  "cancelledBy": zod.union([zod.enum(['customer', 'provider']),zod.null()]),
  "completedAt": zod.coerce.date().nullable()
})
})


